async function openContractManagement() {

    const homePage =
        document.getElementById(
            "homePage"
        );


    const dashboard =
        document.getElementById(
            "dashboard"
        );


    const contractPage =
        document.getElementById(
            "contractManagementPage"
        );


    const usersPage =
        document.getElementById(
            "userManagementPage"
        );


    if (homePage) {

        homePage.style.display =
            "none";

    }


    if (dashboard) {

        dashboard.style.display =
            "block";

    }

const commonHeader =
    document.getElementById(
        "commonHeader"
    );


if (commonHeader) {

    commonHeader.style.display =
        "flex";

}


    if (contractPage) {

        contractPage.style.display =
            "block";

    }


    if (usersPage) {

        usersPage.style.display =
            "none";

    }


    currentPage =
        "contracts";


    closeUserMenu();

    closeAllModals();

    scrollToTop();

    contractCurrentSectionId =
    null;


await showContractHome()

await loadContractSections();

await loadContractOptions();

}

/* =========================================================
   OPEN CONTRACT SECTION
========================================================= */

async function openContractSection(
    sectionId
){

    /*
        -----------------------------------------------------
        HOME
        -----------------------------------------------------
    */

    if(
        sectionId ===
        "home"
    ){

        showContractHome();

        return;

    }


    /*
        -----------------------------------------------------
        VALIDATE SECTION
        -----------------------------------------------------
    */

    const section =
        contractSections[
            sectionId
        ];


    if(
        !section
    ){

        console.warn(
            "CONTRACT SECTION NOT FOUND:",
            sectionId
        );

        showInterfaceMessage(
            "The selected section could not be found."
        );

        return;

    }


    /*
        -----------------------------------------------------
        SAVE CURRENT SECTION
        -----------------------------------------------------
    */

    contractCurrentSectionId =
        sectionId;


    /*
        -----------------------------------------------------
        CONTRACT MANAGEMENT HOME
        -----------------------------------------------------
    */

    const home =
        document.querySelector(
            ".contract-management-home"
        );


    if(
        home
    ){

        home.style.display =
            "none";

    }


    /*
        -----------------------------------------------------
        SECTION VIEW
        -----------------------------------------------------

        If the HTML does not contain the view yet,
        create it automatically.

        This prevents the navigation from breaking
        if the section-view markup has not been added.
    */

    let sectionView =
        document.getElementById(
            "contractSectionView"
        );


    if(
        !sectionView
    ){

        const contractContent =
            document.getElementById(
                "contractContent"
            );


        if(
            !contractContent
        ){

            console.error(
                "CONTRACT CONTENT CONTAINER NOT FOUND."
            );

            return;

        }


        sectionView =
            document.createElement(
                "section"
            );


        sectionView.id =
            "contractSectionView";


        sectionView.className =
            "contract-section-view";


        sectionView.innerHTML = `

            <div
                class="contract-section-view-header"
            >

                <button
    id="homeNavigationButton"
    class="
        financial-header-home-only
    "
    type="button"
    onclick="openContractSection('home')"
>

    <span
    class="contract-section-card-icon"
    aria-hidden="true"
>
    <span class="contract-icon-home">
    
    </span>



    <div
        class="contract-section-card-content"
    >

        <strong>

            Home

        </strong>


        <small>

            All contracts

        </small>

    </div>


    <span
        class="contract-section-card-arrow"
    >

        →

    </span>

</button>


                <div
                    class="contract-section-view-heading"
                >

                    <span
                        class="
                            contract-section-eyebrow
                        "
                    >

                        CONTRACT SECTION

                    </span>


                    <h2
                        class="
                            contract-section-view-title
                        "
                    >

                        Section

                    </h2>


                    <p
                        class="
                            contract-section-view-subtitle
                        "
                    >

                        Contracts organised in this section.

                    </p>

                </div>


                <div
                    class="
                        contract-section-view-actions
                    "
                >

                    ${
                        authSystem.isAdmin()
                            ? `
                                <button
                                    type="button"
                                    class="
                                        modal-primary-button
                                    "
                                    onclick="
    openCreateContract(
        '${uiEscapeJS(sectionId)}'
    )
"
                                >

                                    + ADD CONTRACT

                                </button>
                            `
                            : ""
                    }

                </div>

            </div>


            <div
                class="
                    contract-section-view-toolbar
                "
            >

                <div
                    class="
                        contract-section-view-stat
                    "
                >

                    <strong
    id="contractSectionContractCount"
>

                        0

                    </strong>


                    <span>

                        Contracts

                    </span>

                </div>


                <div
    id="contractSectionContracts"
    class="
        contract-section-contracts-list
    "
></div>

            </div>

        `;


        contractContent.appendChild(
            sectionView
        );

    }


    /*
        -----------------------------------------------------
        SHOW SECTION VIEW
        -----------------------------------------------------
    */

    sectionView.style.display =
        "block";


    /*
        -----------------------------------------------------
        UPDATE SECTION TITLE
        -----------------------------------------------------
    */

    const title =
        sectionView.querySelector(
            ".contract-section-view-title"
        );


    if(
        title
    ){

        title.textContent =
            section.name ||
            "Section";

    }


    /*
        -----------------------------------------------------
        UPDATE SUBTITLE
        -----------------------------------------------------
    */

    const subtitle =
        sectionView.querySelector(
            ".contract-section-view-subtitle"
        );


    if(
        subtitle
    ){

        subtitle.textContent =
            "Contracts organised in this section.";

    }


    /*
        -----------------------------------------------------
        REFRESH SECTION NAVIGATION
        -----------------------------------------------------
    */

    renderContractSections();


    /*
        -----------------------------------------------------
        LOAD LATEST CONTRACT DATA
        -----------------------------------------------------
    */

        try {

        await loadContracts();

        renderContractsInSection(
            sectionId
        );

    }
    catch(error){

        console.error(
            "CONTRACT SECTION LOAD ERROR:",
            error
        );

    }


    /*
        -----------------------------------------------------
        SCROLL
        -----------------------------------------------------
    */

    scrollToTop();

}

/* =========================================================
   USER MENU
========================================================= */

function toggleUserMenu(
    event
) {

    if (event) {

        event.stopPropagation();

    }


    const menu =
        document.getElementById(
            "userMenu"
        );


    if (!menu) {

        return;

    }


    userMenuOpen =
        !userMenuOpen;

if (
    userMenuOpen &&
    event &&
    event.currentTarget &&
    event.currentTarget.id === "homeUserCard"
) {

    menu.classList.add(
        "home-user-menu"
    );

} else {

    menu.classList.remove(
        "home-user-menu"
    );

}

    menu.style.display =
        userMenuOpen
            ? "block"
            : "none";

}

// =========================================================
// GLOBAL FUNCTIONS FOR HTML ONCLICK HANDLERS
// =========================================================

window.toggleUserMenu =
    toggleUserMenu;

function closeUserMenu() {

    const menu =
        document.getElementById(
            "userMenu"
        );


    if (!menu) {

        return;

    }


    userMenuOpen =
        false;


    menu.style.display =
        "none";

}

