function openLoginModal(){

    createAuthenticationModals();

    closeAuthenticationModals();


    const modal =
        document.getElementById(
            "loginModal"
        );


    if(
        !modal
    ){

        return;

    }


    const username =
        document.getElementById(
            "loginUsername"
        );


    const password =
        document.getElementById(
            "loginPassword"
        );


    const error =
        document.getElementById(
            "loginError"
        );


    if(
        username
    ){

        username.value =
            "";

    }


    if(
        password
    ){

        password.value =
            "";

    }


    if(
        error
    ){

        error.hidden =
            true;

        error.textContent =
            "";

    }


    modal.classList.add(
        "open"
    );


    modal.setAttribute(
        "aria-hidden",
        "false"
    );


    document.body.style.overflow =
        "hidden";


    setTimeout(

        () => {

            username?.focus();

        },

        120

    );

}


/* =========================================================
   LOGIN SUBMIT
========================================================= */

async function handleLoginSubmit(){

    const username =
        document
            .getElementById(
                "loginUsername"
            )
            ?.value
            .trim();


    const password =
        document
            .getElementById(
                "loginPassword"
            )
            ?.value;


    const error =
        document.getElementById(
            "loginError"
        );


    const button =
        document.getElementById(
            "loginButton"
        );


    if(
        error
    ){

        error.hidden =
            true;

    }


    if(
        !username
    ){

        if(
            error
        ){

            error.textContent =
                "Please enter your username.";

            error.hidden =
                false;

        }


        return;

    }


    if(
        !password
    ){

        if(
            error
        ){

            error.textContent =
                "Please enter your password.";

            error.hidden =
                false;

        }


        return;

    }


    button.disabled =
        true;


    button.innerHTML =
        "SIGNING IN...";


    try{

        const result =
            await authSystem.loginUser(

                username,

                password

            );


        if(
            !result?.success
        ){

            throw new Error(
                result?.error ||
                "LOGIN_ERROR"
            );

        }


        window.financialAuthState = {

            authenticated:
                true,

            firstInstallation:
                false,

            user:
                result.user

        };


        closeAuthenticationModals();


        updateAuthenticatedInterface();


        showHome();


        startClock();

    }
    catch(errorObject){

        console.error(
            "LOGIN ERROR:",
            errorObject
        );


        if(
            error
        ){

            error.textContent =
                authSystem.getAuthErrorMessage(
                    errorObject?.message ||
                    "LOGIN_ERROR"
                );


            error.hidden =
                false;

        }

    }
    finally{

        button.disabled =
            false;


        button.innerHTML =
            "SIGN IN <span>→</span>";

    }

}


/* =========================================================
   FIRST ADMINISTRATOR SUBMIT
========================================================= */

async function handleFirstAdministratorSubmit(){

    clearFirstAdminValidation();


    const fullName =
        document
            .getElementById(
                "setupFullName"
            )
            ?.value
            .trim();


    const username =
        document
            .getElementById(
                "setupUsername"
            )
            ?.value
            .trim()
            .toLowerCase();


    const password =
        document
            .getElementById(
                "setupPassword"
            )
            ?.value;


    const password2 =
        document
            .getElementById(
                "setupPassword2"
            )
            ?.value;


    const masterKey =
        document
            .getElementById(
                "setupMasterKey"
            )
            ?.value;


    const button =
        document.getElementById(
            "createFirstAdminButton"
        );


    /* ======================================================
       LOCAL VALIDATION
    ====================================================== */

    if(
        !fullName
    ){

        showFirstAdminValidation(
            "Please enter your full name."
        );


        document
            .getElementById(
                "setupFullName"
            )
            ?.focus();


        return;

    }


    if(
        !validateFirstAdminUsername()
    ){

        showFirstAdminValidation(
            "Username must contain 3–32 characters and use only letters, numbers, \"_\" or \"-\". Spaces and dots are not allowed."
        );


        document
            .getElementById(
                "setupUsername"
            )
            ?.focus();


        return;

    }


    if(
        !validateFirstAdminPassword()
    ){

        showFirstAdminValidation(
            "Password must contain at least 8 characters."
        );


        document
            .getElementById(
                "setupPassword"
            )
            ?.focus();


        return;

    }


    if(
        !validateFirstAdminPasswordMatch()
    ){

        showFirstAdminValidation(
            "The confirmation password does not match."
        );


        document
            .getElementById(
                "setupPassword2"
            )
            ?.focus();


        return;

    }


    if(
        !validateFirstAdminMasterKey()
    ){

        showFirstAdminValidation(
            "Master Security Key must contain at least 8 characters."
        );


        document
            .getElementById(
                "setupMasterKey"
            )
            ?.focus();


        return;

    }


    /* ======================================================
       CREATE
    ====================================================== */

    button.disabled =
        true;


    button.innerHTML =
        "CREATING ADMINISTRATOR...";


    try{

        const photo =
            await readFirstAdminPhoto();


        const result =
            await authSystem.createFirstAdministrator({

                fullName,

                username,

                password,

                masterKey,

                photo

            });


        window.financialAuthState = {

            authenticated:
                true,

            firstInstallation:
                false,

            user:
                result

        };


        closeAuthenticationModals();


        updateAuthenticatedInterface();


        showHome();


        startClock();

    }
    catch(errorObject){

        console.error(
            "FIRST ADMINISTRATOR ERROR:",
            errorObject
        );


        const code =
            errorObject?.message ||
            "LOGIN_ERROR";


        /*
           Important:
           We do NOT blindly say "incorrect".

           Every error has a specific user-facing
           explanation in auth.js.
        */

        showFirstAdminValidation(

            authSystem.getAuthErrorMessage(
                code
            )

        );

    }
    finally{

        button.disabled =
            false;


        button.innerHTML =
            "CREATE ADMINISTRATOR <span>→</span>";

    }

}


/* =========================================================
   READ FIRST ADMIN PHOTO
========================================================= */

async function readFirstAdminPhoto(){

    const file =
        document
            .getElementById(
                "setupPhotoInput"
            )
            ?.files?.[0];


    if(
        !file
    ){

        return null;

    }


    if(
        typeof authSystem !==
        "undefined" &&
        typeof authSystem.readPhotoAsDataURL ===
        "function"
    ){

        return await authSystem.readPhotoAsDataURL(
            file
        );

    }


    return new Promise(

        (resolve,reject) => {

            const reader =
                new FileReader();


            reader.onload =
                event => {

                    resolve(
                        event.target.result
                    );

                };


            reader.onerror =
                () => {

                    reject(
                        new Error(
                            "PHOTO_READ_FAILED"
                        )
                    );

                };


            reader.readAsDataURL(
                file
            );

        }

    );

}


