    null;

let auditLogsCache = [];

/* =========================================================
   GENERIC HELPERS
========================================================= */

function uiEscape(
    value
){

    return String(
        value ?? ""
    )
    .replace(
        /&/g,
        "&amp;"
    )
    .replace(
        /</g,
        "&lt;"
    )
    .replace(
        />/g,
        "&gt;"
    )
    .replace(
        /"/g,
        "&quot;"
    )
    .replace(
        /'/g,
        "&#039;"
    );

}


function uiEscapeJS(
    value
){

    return String(
        value ?? ""
    )
    .replace(
        /\\/g,
        "\\\\"
    )
    .replace(
        /'/g,
        "\\'"
    )
    .replace(
        /\r/g,
        "\\r"
    )
    .replace(
        /\n/g,
        "\\n"
    );

}


function formatDateTime(
    value
){

    if(
        !value
    ){

        return "—";

    }


    const date =
        new Date(
            Number(value)
        );


    if(
        Number.isNaN(
            date.getTime()
        )
    ){

        return "—";

    }


    return date.toLocaleString(
        "en-GB",
        {

            day:
                "2-digit",

            month:
                "2-digit",

            year:
                "numeric",

            hour:
                "2-digit",

            minute:
                "2-digit"

        }
    );

}


function getUserInitialsUI(
    name
){

    if(
        typeof authSystem?.getUserInitials ===
        "function"
    ){

        return authSystem.getUserInitials(
            name
        );

    }


    const parts =
        String(
            name || ""
        )
        .trim()
        .split(
            /\s+/
        );


    if(
        parts.length === 0 ||
        !parts[0]
    ){

        return "U";

    }


    if(
        parts.length === 1
    ){

        return parts[0]
            .substring(
                0,
                2
            )
            .toUpperCase();

    }


    return (
        parts[0][0] +
        parts[parts.length - 1][0]
    ).toUpperCase();

}

