/* =========================================================
   REAL LOGOUT
========================================================= */

async function performLogout(){

    try{

        /*
            Close the confirmation modal first.
        */

        closeLogoutConfirmation();


        /*
            Close any other open interface elements.
        */

        closeAllModals();

        closeUserMenu();


        /*
            Perform the REAL logout through authSystem.

            auth.js handles:
            - Audit Log
            - session cleanup
            - current user cleanup
            - Firebase/application session state
            - logout event
        */

        await authSystem.logoutUser();


        /*
            Clear any protected action that was waiting
            for Administrator authentication.
        */

        pendingAdminAction =
            null;


        /*
            Return to the public Home Page.
        */

        showHome();


        /*
            Refresh the authenticated / guest interface.
        */

        if(
            typeof updateAuthenticatedInterface ===
            "function"
        ){

            updateAuthenticatedInterface();

        }


        /*
            Make absolutely sure the User Menu
            is closed after the interface refresh.
        */

        closeUserMenu();


        /*
            Return the page to the top.
        */

        window.scrollTo(
            0,
            0
        );

    }
    catch(error){

        console.error(
            "LOGOUT ERROR:",
            error
        );


        closeLogoutConfirmation();


        closeUserMenu();


        showInterfaceMessage(
            "Unable to complete logout. Please try again."
        );

    }

}


/* =========================================================
   REAL LOGOUT — GLOBAL API
========================================================= */

window.performLogout =
    performLogout;



