async function saveEditedUser(
    username
){

    const fullName =
        document.getElementById(
            "editUserFullName"
        )?.value.trim();


    if(
        !fullName
    ){

        showInterfaceMessage(
            "Please enter the user's full name."
        );

        return;

    }


    try{

        await authSystem.adminUpdateUser(

            username,

            {

                fullName:
                    fullName

            }

        );


        closeDynamicModal(
            "editUserModal"
        );


        closeUserActions();


        await loadUserManagement();


        showInterfaceMessage(
            "User updated successfully."
        );

    }
    catch(error){

        handleUserManagementError(
            error
        );

    }

}


