async function saveUserRole(
    username
){

    const role =
        document.getElementById(
            "changeRoleSelect"
        )?.value;


    const masterKey =
        document.getElementById(
            "changeRoleMasterKey"
        )?.value;


    if(
        !masterKey ||
        masterKey.length < 8
    ){

        showInterfaceMessage(
            "Master Security Key must contain at least 8 characters."
        );

        return;

    }


    try{

        await authSystem.changeUserRole(

            username,

            role,

            masterKey

        );


        closeDynamicModal(
            "changeRoleModal"
        );


        closeUserActions();


        await loadUserManagement();


        showInterfaceMessage(
            "User role updated successfully."
        );

    }
    catch(error){

        handleUserManagementError(
            error
        );

    }

}


