async function executeAdminPasswordReset(
    username
){

    const password =
        document.getElementById(
            "adminNewPassword"
        )?.value || "";


    const confirmation =
        document.getElementById(
            "adminNewPasswordConfirm"
        )?.value || "";


    const masterKey =
        document.getElementById(
            "adminPasswordMasterKey"
        )?.value || "";


    if(
        password.length < 8
    ){

        showInterfaceMessage(
            "Password must contain at least 8 characters."
        );

        return;

    }


    if(
        password !==
        confirmation
    ){

        showInterfaceMessage(
            "The passwords do not match."
        );

        return;

    }


    if(
        masterKey.length < 8
    ){

        showInterfaceMessage(
            "Master Security Key must contain at least 8 characters."
        );

        return;

    }


    try{

        await authSystem.adminResetUserPassword({

            username:
                username,

            newPassword:
                password,

            masterKey:
                masterKey

        });


        closeDynamicModal(
            "resetPasswordModal"
        );


        closeUserActions();


        showInterfaceMessage(
            "Password reset successfully."
        );

    }
    catch(error){

        handleUserManagementError(
            error
        );

    }

}


/* =========================================================
   ACTIVE / INACTIVE
========================================================= */

async function toggleUserActiveState(
    username,
    active
){

    const action =
        active
            ? "activate"
            : "deactivate";


    const confirmed =
    await requestActionConfirmation({

        title:
            active
                ? "ACTIVATE USER"
                : "DEACTIVATE USER",

        subtitle:
            `@${username}`,

        message:
            active
                ? "This user will regain access to the Financial Dashboard."
                : "This user will no longer be able to access the Financial Dashboard.",

        confirmText:
            active
                ? "ACTIVATE USER"
                : "DEACTIVATE USER",

        cancelText:
            "CANCEL",

        icon:
            active
                ? "✅"
                : "⛔",

        danger:
            !active

    });


if(
    !confirmed
){

    return;

}


    const masterKey =
        await requestMasterKey(
            active
                ? "Activate User"
                : "Deactivate User"
        );


    if(
        !masterKey
    ){

        return;

    }


    try{

        await authSystem.setUserActiveState(

            username,

            active,

            masterKey

        );


        closeUserActions();


        await loadUserManagement();


        showInterfaceMessage(
            active
                ? "User activated successfully."
                : "User deactivated successfully."
        );

    }
    catch(error){

        handleUserManagementError(
            error
        );

    }

}


/* =========================================================
   ARCHIVE / RESTORE
========================================================= */

async function toggleUserArchiveState(
    username,
    archive
){

    const action =
        archive
            ? "archive"
            : "restore";


    const confirmed =
    await requestActionConfirmation({

        title:
            archive
                ? "ARCHIVE USER"
                : "RESTORE USER",

        subtitle:
            `@${username}`,

        message:
            archive
                ? "The user will be archived and removed from the active user list."
                : "The user will be restored and become available again.",

        confirmText:
            archive
                ? "ARCHIVE USER"
                : "RESTORE USER",

        cancelText:
            "CANCEL",

        icon:
            archive
                ? "📦"
                : "↩️",

        danger:
            false

    });


if(
    !confirmed
){

    return;

}


    const masterKey =
        await requestMasterKey(
            archive
                ? "Archive User"
                : "Restore User"
        );


    if(
        !masterKey
    ){

        return;

    }


    try{

        if(
            archive
        ){

            await authSystem.archiveUser(
                username,
                masterKey
            );

        }
        else{

            await authSystem.unarchiveUser(
                username,
                masterKey
            );

        }


        closeUserActions();


        await loadUserManagement();


        showInterfaceMessage(
            archive
                ? "User archived successfully."
                : "User restored successfully."
        );

    }
    catch(error){

        handleUserManagementError(
            error
        );

    }

}


/* =========================================================
   DELETE USER
========================================================= */

async function deleteManagedUser(
    username
){

    
    const masterKey =
        await requestMasterKey(
            "Delete User"
        );


    if(
        !masterKey
    ){

        return;

    }


    try{

        await authSystem.deleteUser(

            username,

            masterKey

        );


        closeUserActions();


        await loadUserManagement();


        showInterfaceMessage(
            "User permanently deleted."
        );

    }
    catch(error){

        handleUserManagementError(
            error
        );

    }

}


/* =========================================================
   MASTER KEY MODAL
========================================================= */

function requestMasterKey(
    title
){

    return new Promise(

        resolve => {

            const modal =
                createDynamicModal(
                    "masterKeyModal",
                    "SECURITY VERIFICATION",
                    title
                );


            modal.body.innerHTML = `

                <div
                    style="
                        text-align:center;
                        margin-bottom:20px;
                    "
                >

                    <div
                        style="
                            font-size:38px;
                            margin-bottom:12px;
                        "
                    >

                        🔐

                    </div>


                    <p
                        style="
                            font-size:14px;
                            line-height:1.6;
                        "
                    >

                        This action requires your
                        Master Security Key.

                    </p>

                </div>


                <div
                    class="settings-field"
                >

                    <label>

                        Master Security Key

                    </label>


                    <input
                        id="masterKeyVerificationInput"
                        type="password"
                        minlength="8"
                        placeholder="Enter Master Security Key"
                    >

                </div>

            `;


            modal.footer.innerHTML = `

                <button
                    type="button"
                    class="modal-secondary-button"
                    onclick="
                        resolveMasterKey(
                            null
                        )
                    "
                >

                    CANCEL

                </button>


                <button
                    type="button"
                    class="modal-primary-button"
                    onclick="
                        resolveMasterKey(
                            document.getElementById(
                                'masterKeyVerificationInput'
                            )?.value
                        )
                    "
                >

                    VERIFY & CONTINUE

                </button>

            `;


            window.__resolveMasterKey =
                resolve;


            modal.open();

        }

    );

}


function resolveMasterKey(
    key
){

    closeDynamicModal(
        "masterKeyModal"
    );


    const resolver =
        window.__resolveMasterKey;


    window.__resolveMasterKey =
        null;


    if(
        resolver
    ){

        resolver(
            key &&
            key.length >= 8
                ? key
                : null
        );

    }

}

/* =========================================================
   GENERIC CONFIRMATION MODAL
   Reusable for DELETE / ARCHIVE / MOVE / DEACTIVATE / etc.
========================================================= */

function requestActionConfirmation(
    options = {}
){

    return new Promise(

        resolve => {

            const title =
                options.title ||
                "CONFIRM ACTION";


            const message =
                options.message ||
                "Are you sure you want to continue?";


            const confirmText =
                options.confirmText ||
                "CONTINUE";


            const cancelText =
                options.cancelText ||
                "CANCEL";


            const requireText =
                options.requireText ||
                "";


            const icon =
                options.icon ||
                "⚠️";


            const danger =
                options.danger !== false;


            const modal =
                createDynamicModal(
                    "actionConfirmationModal",
                    title,
                    options.subtitle ||
                    "Please confirm this action"
                );


            /*
                -------------------------------------------------
                MESSAGE
                -------------------------------------------------
            */

            modal.body.innerHTML = `

                <div
                    class="
                        action-confirmation-content
                        ${danger
                            ? "action-confirmation-danger"
                            : ""}
                    "
                >

                    <div
                        class="
                            action-confirmation-icon
                        "
                    >

                        ${icon}

                    </div>


                    <div
                        class="
                            action-confirmation-message
                        "
                    >

                        ${message}

                    </div>


                    ${
                        requireText
                            ? `

                                <div
                                    class="
                                        settings-field
                                        action-confirmation-input
                                    "
                                >

                                    <label>

                                        Type
                                        <strong>
                                            ${requireText}
                                        </strong>
                                        to confirm

                                    </label>


                                    <input
                                        id="
                                            actionConfirmationInput
                                        "
                                        type="text"
                                        autocomplete="off"
                                        spellcheck="false"
                                        placeholder="
                                            Type ${requireText}
                                        "
                                    >

                                </div>

                            `
                            : ""
                    }

                </div>

            `;


            /*
                -------------------------------------------------
                FOOTER
                -------------------------------------------------
            */

            modal.footer.innerHTML = `

                <button
                    type="button"
                    class="modal-secondary-button"
                    onclick="
                        resolveActionConfirmation(
                            false
                        )
                    "
                >

                    ${cancelText}

                </button>


                <button
                    type="button"
                    class="
                        modal-primary-button
                        ${
                            danger
                                ? "confirmation-danger-button"
                                : ""
                        }
                    "
                    onclick="
                        resolveActionConfirmation(
                            true
                        )
                    "
                >

                    ${confirmText}

                </button>

            `;


            /*
                -------------------------------------------------
                STORE RESOLVER
                -------------------------------------------------
            */

            window.__actionConfirmationResolver =
                resolve;


            window.__actionConfirmationRequiredText =
                requireText;


            modal.open();


            /*
                Focus the confirmation input automatically.
            */

            if(
                requireText
            ){

                setTimeout(

                    () => {

                        const input =
                            document.getElementById(
                                "actionConfirmationInput"
                            );


                        if(
                            input
                        ){

                            input.focus();

                        }

                    },

                    120

                );

            }

        }

    );

}


/* =========================================================
   RESOLVE GENERIC CONFIRMATION
========================================================= */

function resolveActionConfirmation(
    confirmed
){

    const resolver =
        window.__actionConfirmationResolver;


    const requiredText =
        window.__actionConfirmationRequiredText ||
        "";


    /*
        -----------------------------------------------------
        CANCEL
        -----------------------------------------------------
    */

    if(
        !confirmed
    ){

        window.__actionConfirmationResolver =
            null;

        window.__actionConfirmationRequiredText =
            "";


        closeDynamicModal(
            "actionConfirmationModal"
        );


        if(
            resolver
        ){

            resolver(
                false
            );

        }


        return;

    }


    /*
        -----------------------------------------------------
        TEXT VERIFICATION
        -----------------------------------------------------
    */

    if(
        requiredText
    ){

        const input =
            document.getElementById(
                "actionConfirmationInput"
            );


        const value =
            input?.value.trim() ||
            "";


        if(
            value !==
            requiredText
        ){

            showInterfaceMessage(
                `Please type ${requiredText} exactly to confirm.`
            );


            if(
                input
            ){

                input.focus();

            }


            return;

        }

    }


    /*
        -----------------------------------------------------
        CONFIRMED
        -----------------------------------------------------
    */

    window.__actionConfirmationResolver =
        null;

    window.__actionConfirmationRequiredText =
        "";


    closeDynamicModal(
        "actionConfirmationModal"
    );


    if(
        resolver
    ){

        resolver(
            true
        );

    }

}


/* =========================================================
   GLOBAL ONCLICK API
========================================================= */

window.requestActionConfirmation =
    requestActionConfirmation;


window.resolveActionConfirmation =
    resolveActionConfirmation;

/* =========================================================
   DYNAMIC MODAL ENGINE
========================================================= */

function createDynamicModal(
    id,
    title,
    subtitle
){

    let overlay =
        document.getElementById(
            id
        );


    if(
        overlay
    ){

        overlay.remove();

    }


    overlay =
        document.createElement(
            "div"
        );


    overlay.id =
        id;


    overlay.className =
        "modal-overlay";


    overlay.innerHTML = `

        <div
            class="
                modal-window
                modal-window-medium
            "
            role="dialog"
            aria-modal="true"
        >

            <div class="modal-header">

                <div
                    class="modal-header-title"
                >

                    <div
                        class="modal-header-icon"
                    >

                        ⚙️

                    </div>


                    <div>

                        <h2>

                            ${uiEscape(title)}

                        </h2>


                        <p>

                            ${uiEscape(subtitle)}

                        </p>

                    </div>

                </div>


                <button
                    type="button"
                    class="modal-close-button"
                    onclick="
                        closeDynamicModal(
                            '${uiEscapeJS(id)}'
                        )
                    "
                >

                    ×

                </button>

            </div>


            <div
                class="modal-body"
            ></div>


            <div
                class="modal-footer"
            ></div>

        </div>

    `;


    document.body.appendChild(
        overlay
    );


    return {

        element:
            overlay,

        body:
            overlay.querySelector(
                ".modal-body"
            ),

        footer:
            overlay.querySelector(
                ".modal-footer"
            ),

        open(){

            overlay.classList.add(
                "open"
            );

            overlay.setAttribute(
                "aria-hidden",
                "false"
            );

            document.body.style.overflow =
                "hidden";

        }

    };

}


function closeDynamicModal(
    id
){

    const modal =
        document.getElementById(
            id
        );


    if(
        modal
    ){

        modal.remove();

    }


    if(
        document.querySelectorAll(
            ".modal-overlay.open"
        ).length === 0
    ){

        document.body.style.overflow =
            "";

    }

}

window.closeDynamicModal =
    closeDynamicModal;

/* =========================================================
   USER MANAGEMENT ERROR HANDLER
========================================================= */

function handleUserManagementError(
    error
){

    console.error(
        "USER MANAGEMENT ERROR:",
        error
    );


    const messages = {

        ACCESS_DENIED:
            "You do not have permission to perform this action.",

        USER_NOT_FOUND:
            "The selected user could not be found.",

        INVALID_MASTER_KEY:
            "The Master Security Key is incorrect.",

        CANNOT_DISABLE_CURRENT_USER:
            "You cannot deactivate your own account.",

        CANNOT_DELETE_CURRENT_USER:
            "You cannot delete your own account.",

        CANNOT_DISABLE_LAST_ADMIN:
            "The last Administrator account cannot be deactivated.",

        CANNOT_DELETE_LAST_ADMIN:
            "The last Administrator account cannot be deleted.",

        CANNOT_REMOVE_LAST_ADMIN_ROLE:
            "The last Administrator cannot lose Administrator status.",

        INVALID_PASSWORD:
            "The password does not meet the minimum security requirements.",

        INVALID_FULL_NAME:
            "Please enter a valid full name.",

        USERNAME_ALREADY_EXISTS:
            "That username is already in use."

    };


    showInterfaceMessage(

        messages[
            error?.message
        ] ||

        "The requested operation could not be completed."

    );

}

/* =========================================================
   GLOBAL INTERFACE MESSAGE
   TOPMOST APPLICATION NOTIFICATION
========================================================= */

function showInterfaceMessage(
    message
){

    /*
        -----------------------------------------------------
        REMOVE PREVIOUS MESSAGE LAYER
        -----------------------------------------------------
    */

    const oldLayer =
        document.getElementById(
            "interfaceMessageLayer"
        );


    if(
        oldLayer
    ){

        oldLayer.remove();

    }


    /*
        -----------------------------------------------------
        CREATE TOPMOST LAYER
        -----------------------------------------------------
    */

    const layer =
        document.createElement(
            "div"
        );


    layer.id =
        "interfaceMessageLayer";


    layer.setAttribute(
        "aria-live",
        "assertive"
    );


    layer.setAttribute(
        "aria-atomic",
        "true"
    );


    /*
        IMPORTANT:
        Append to <html>, not inside any modal.
    */

    document.documentElement.appendChild(
        layer
    );


    /*
        -----------------------------------------------------
        LAYER POSITION
        -----------------------------------------------------
    */

    Object.assign(

        layer.style,

        {

            position:
                "fixed",

            inset:
                "0",

            width:
                "100vw",

            height:
                "100vh",

            zIndex:
                "2147483647",

            pointerEvents:
                "none",

            display:
                "flex",

            justifyContent:
                "flex-end",

            alignItems:
                "flex-start",

            padding:
                "24px",

            boxSizing:
                "border-box",

            isolation:
                "isolate"

        }

    );


    /*
        -----------------------------------------------------
        CREATE MESSAGE
        -----------------------------------------------------
    */

    const toast =
        document.createElement(
            "div"
        );


    toast.id =
        "interfaceMessageToast";


    toast.setAttribute(
        "role",
        "alert"
    );


    /*
        Force the message into plain text.
    */

    toast.textContent =
        String(
            message ??
            ""
        );


    /*
        -----------------------------------------------------
        TOAST STYLE
        -----------------------------------------------------
    */

    Object.assign(

        toast.style,

        {

            display:
                "block",

            position:
                "relative",

            width:
                "fit-content",

            maxWidth:
                "min(440px, calc(100vw - 48px))",

            minHeight:
                "48px",

            padding:
                "14px 18px",

            boxSizing:
                "border-box",

            borderRadius:
                "12px",

            background:
                "#0b2a63",

            color:
                "#ffd200",

            fontFamily:
                "Inter, Arial, sans-serif",

            fontSize:
                "14px",

            fontWeight:
                "700",

            lineHeight:
                "1.45",

            textAlign:
                "left",

            whiteSpace:
                "normal",

            wordBreak:
                "break-word",

            opacity:
                "0",

            transform:
                "translate3d(0,-12px,0)",

            visibility:
                "hidden",

            boxShadow:
                "0 18px 45px rgba(0,0,0,0.35)",

            border:
                "1px solid rgba(255,255,255,0.18)",

            transition:
                "opacity 180ms ease, transform 220ms cubic-bezier(0.22,1,0.36,1)",

            pointerEvents:
                "none",

            flex:
                "0 0 auto"

        }

    );


    /*
        -----------------------------------------------------
        ADD TO TOPMOST LAYER
        -----------------------------------------------------
    */

    layer.appendChild(
        toast
    );


    /*
        -----------------------------------------------------
        FORCE BROWSER PAINT
        -----------------------------------------------------
    */

    requestAnimationFrame(

        () => {

            requestAnimationFrame(

                () => {

                    toast.style.visibility =
                        "visible";


                    toast.style.opacity =
                        "1";


                    toast.style.transform =
                        "translate3d(0,0,0)";

                }

            );

        }

    );


    /*
        -----------------------------------------------------
        AUTO REMOVE
        -----------------------------------------------------
    */

    setTimeout(

        () => {

            if(
                !toast.isConnected
            ){

                return;

            }


            toast.style.opacity =
                "0";


            toast.style.transform =
                "translate3d(0,-12px,0)";


            setTimeout(

                () => {

                    if(
                        layer.isConnected
                    ){

                        layer.remove();

                    }

                },

                220

            );

        },

        3200

    );

}


