/* =========================================================
   CLOCK
========================================================= */

function startClock() {

    updateClock();


    if (clockInterval) {

        clearInterval(
            clockInterval
        );

    }


    clockInterval =
        setInterval(
            updateClock,
            1000
        );

}


function updateClock() {

    const now =
        new Date();


    const time =
        now.toLocaleTimeString(
            "en-GB",
            {

                hour:
                    "2-digit",

                minute:
                    "2-digit",

                second:
                    "2-digit"

            }
        );


    const date =
        now.toLocaleDateString(
            "en-GB",
            {

                day:
                    "2-digit",

                month:
                    "2-digit",

                year:
                    "numeric"

            }
        );


    const headerClock =
        document.getElementById(
            "headerClock"
        );


    const homeTime =
        document.getElementById(
            "homeTime"
        );


    const homeDate =
        document.getElementById(
            "homeDate"
        );


    if (headerClock) {

        headerClock.textContent =
            time;

    }


    if (homeTime) {

        homeTime.textContent =
            time;

    }


    if (homeDate) {

        homeDate.textContent =
            date;

    }

}


/* =========================================================
   REAL USER LOGOUT
========================================================= */

async function logoutUser(){

    try{

        /*
            Keep the current user information before
            terminating the session so the audit record
            can identify who logged out.
        */

        const currentUsername =
            authSystem.getCurrentUsername();


        /*
            Close all interface elements first.
        */

        closeAllModals();

        closeUserMenu();


        /*
            Real Firebase / application logout.

            authSystem.logoutUser() terminates the
            authenticated session and records the
            logout event.
        */

        await authSystem.logoutUser();


        /*
            Clear protected / authenticated interface.
        */

        if(
            typeof updateAuthenticatedInterface ===
            "function"
        ){

            updateAuthenticatedInterface();

        }


        /*
            Clear any pending protected action.
        */

        pendingAdminAction =
            null;


        /*
            Reset the application scroll position.
        */

        window.scrollTo(
            0,
            0
        );


        /*
            IMPORTANT:
            Never return to Home as Guest.

            After logout the application must show
            the startup Welcome screen, where the
            user can SIGN IN or CREATE ACCOUNT.
        */

        if(
            typeof openStartupWelcome ===
            "function"
        ){

            openStartupWelcome();

        }


        /*
            Make sure the user menu remains closed.
        */

        closeUserMenu();


    }
    catch(error){

        console.error(
            "LOGOUT ERROR:",
            error
        );


        /*
            Do not leave protected interface elements
            open if logout fails.
        */

        closeAllModals();

        closeUserMenu();


        /*
            Use the dashboard notification system.
        */

        if(
            typeof window.showInterfaceMessage ===
            "function"
        ){

            window.showInterfaceMessage(
                "Unable to complete logout. Please try again."
            );

        }

    }

}

