document.addEventListener(
    "click",
    (event) => {

        const overlay =
            event.target.closest(
                ".modal-overlay"
            );


        if (!overlay) {

            return;

        }


        /*
            Only close when the user clicks
            the dark area itself.

            Clicking inside the modal does
            nothing.
        */

        if (
            event.target ===
            overlay
        ) {

            closeModal(
                overlay.id
            );

        }

    }
);


