/* =========================================================
   EXPORT SELECTED REPORT
========================================================= */

async function exportSelectedContractMonthlyReport(){

    try{

        /* =============================================
           GET SELECTED REPORTING PERIOD
        ============================================= */

        const monthSelect =
            document.getElementById(
                "contractReportMonth"
            );


        const yearSelect =
            document.getElementById(
                "contractReportYear"
            );


        if(
            !monthSelect ||
            !yearSelect
        ){

            showInterfaceMessage(
                "Unable to determine the selected reporting period."
            );

            return;

        }


        /* =============================================
           READ THE ACTUAL SELECTED OPTION
           ------------------------------------------------
           IMPORTANT:

           We do NOT rely directly on monthSelect.value.

           The option may use:
               0–11
           or:
               1–12

           Instead we read the visible month name.

           Therefore:

               August → 8
               September → 9
               etc.
        ============================================= */

        const selectedMonthOption =
            monthSelect.options[
                monthSelect.selectedIndex
            ];


        const selectedMonthLabel =
            selectedMonthOption
                ? selectedMonthOption.textContent.trim()
                : "";


        const monthNames = {

            january:
                1,

            february:
                2,

            march:
                3,

            april:
                4,

            may:
                5,

            june:
                6,

            july:
                7,

            august:
                8,

            september:
                9,

            october:
                10,

            november:
                11,

            december:
                12

        };


        const normalizedMonthLabel =
            selectedMonthLabel
                .toLowerCase()
                .trim();


        let month =
            monthNames[
                normalizedMonthLabel
            ];


        /* =============================================
           FALLBACK
           ------------------------------------------------
           If the option text is not a normal month name,
           use its numeric value.

           This keeps the function compatible with
           other versions of the modal.
        ============================================= */

        if(
            !Number.isInteger(
                month
            )
        ){

            const rawMonth =
                Number(
                    monthSelect.value
                );


            if(
                Number.isInteger(
                    rawMonth
                ) &&
                rawMonth >= 1 &&
                rawMonth <= 12
            ){

                month =
                    rawMonth;

            }
            else if(
                Number.isInteger(
                    rawMonth
                ) &&
                rawMonth >= 0 &&
                rawMonth <= 11
            ){

                month =
                    rawMonth + 1;

            }

        }


        /* =============================================
           YEAR
        ============================================= */

        const year =
            Number(
                yearSelect.value
            );


        /* =============================================
           VALIDATION
        ============================================= */

        if(
            !Number.isInteger(
                month
            ) ||
            month < 1 ||
            month > 12 ||
            !Number.isInteger(
                year
            ) ||
            year < 2000 ||
            year > 2100
        ){

            console.error(

                "INVALID CONTRACT REPORT PERIOD:",

                {

                    selectedMonthLabel,

                    rawMonthValue:
                        monthSelect.value,

                    resolvedMonth:
                        month,

                    rawYearValue:
                        yearSelect.value,

                    resolvedYear:
                        year

                }

            );


            showInterfaceMessage(
                "Please select a valid reporting period."
            );

            return;

        }


        /* =============================================
           DEBUG
           ------------------------------------------------
           This should now show:

           August 2026

           as:

           month: 8
           year: 2026
        ============================================= */

        console.info(

            "CONTRACT MONTHLY REPORT PERIOD SELECTED:",

            {

                displayedMonth:
                    selectedMonthLabel,

                month:
                    month,

                year:
                    year

            }

        );


        /* =============================================
           EXPORT BUTTON
        ============================================= */

        const button =
            document.getElementById(
                "contractReportExportButton"
            );


        if(
            button
        ){

            button.disabled =
                true;


            button.innerHTML = `

                <span>
                    ...
                </span>

                GENERATING

            `;

        }


        /* =============================================
           CLOSE CONFIGURATION MODAL
        ============================================= */

        closeDynamicModal(
            "contractMonthlyReportModal"
        );


        /* =============================================
           GENERATE PDF
           ------------------------------------------------
           IMPORTANT:

           We now explicitly pass the resolved
           1–12 month value.

           August = 8
        ============================================= */

        if(
            typeof generateContractMonthlyReport ===
            "function"
        ){

            await generateContractMonthlyReport(

                month,

                year

            );

        }
        else if(
            typeof window.generateContractMonthlyReport ===
            "function"
        ){

            await window.generateContractMonthlyReport(

                month,

                year

            );

        }
        else{

            throw new Error(
                "generateContractMonthlyReport is not available."
            );

        }

    }
    catch(error){

        console.error(

            "CONTRACT MONTHLY REPORT EXPORT ERROR:",

            error

        );


        showInterfaceMessage(

            "Unable to generate the Contract Management Report."

        );

    }

}


