/* =========================================================
   CONTRACT MONTHLY REPORT
   DATA HELPERS — CLEAN SOURCE OF TRUTH
   ---------------------------------------------------------
   Rules:
   • Only current contracts are included
   • Deleted/invalid contracts are ignored
   • Section IDs are NEVER exposed
   • Real section names are resolved from contractSections
   • Reviews are handled by their own review date
========================================================= */

function getContractReportSectionName(
    contract
){

    if(
        !contract
    ){

        return "Home";

    }


    const sectionId =
        contract.sectionId ||
        "home";


    /*
        Use the same section source as
        the Contract Management dashboard.
    */

    let section = null;


    if(
        typeof contractSections !==
        "undefined"
    ){

        section =
            contractSections?.[
                sectionId
            ] ||
            null;

    }


    /*
        Fallback for environments where
        sections are exposed globally.
    */

    if(
        !section &&
        window.contractSections
    ){

        section =
            window.contractSections?.[
                sectionId
            ] ||
            null;

    }


    /*
        HOME
    */

    if(
        String(sectionId) ===
        "home"
    ){

        return "Home";

    }


    /*
        REAL SECTION NAME
    */

    if(
        section?.name
    ){

        return String(
            section.name
        ).trim();

    }


    /*
        Never expose an internal ID.
    */

    return "Home";

}


/* =========================================================
   VALID CURRENT CONTRACT
========================================================= */

function isValidContractForMonthlyReport(
    contract
){

    if(
        !contract ||
        typeof contract !==
        "object"
    ){

        return false;

    }


    /*
        Firebase/cache key without a real contract ID
        should not become a report row.
    */

    if(
        !contract.id
    ){

        return false;

    }


    /*
        Deleted / archived contracts must never
        enter the monthly report.

        These checks are deliberately defensive:
        different historical versions of the data
        may contain different flags.
    */

    if(
        contract.deleted === true ||
        contract.isDeleted === true ||
        contract.archived === true ||
        contract.isArchived === true
    ){

        return false;

    }


    /*
        A contract must have a meaningful identity.
    */

    const name =
        String(
            contract.name ||
            ""
        ).trim();


    if(
        !name
    ){

        return false;

    }


    return true;

}


/* =========================================================
   CURRENT CONTRACT SOURCE
========================================================= */

function getCurrentContractsForMonthlyReport(){

    const cache =
        window.contractsCache ||
        {};


    return Object.values(
        cache
    )
    .filter(
        isValidContractForMonthlyReport
    );

}


/* =========================================================
   REPORT PERIOD CHECK
========================================================= */

function isMonthlyReportDate(
    value,
    year,
    month
){

    if(
        !value
    ){

        return false;

    }


    const date =
        new Date(
            value
        );


    if(
        Number.isNaN(
            date.getTime()
        )
    ){

        return false;

    }


    return (

        date.getFullYear() ===
        Number(year)

        &&

        date.getMonth() ===
        Number(month) - 1

    );

}


/* =========================================================
   REVIEW DATE
   ---------------------------------------------------------
   The report must use the DATE OF THE REVIEW.

   Priority:
       savedAt
       createdAt

   If the existing review has a dedicated reviewDate,
   that takes priority.
========================================================= */

function getContractReportReviewDate(
    review
){

    if(
        !review
    ){

        return null;

    }


    return (

        review.reviewDate ||

        review.savedAt ||

        review.createdAt ||

        null

    );

}


/* =========================================================
   REVIEW VERSION KEY
========================================================= */

function getContractReportReviewVersion(
    review
){

    if(
        !review
    ){

        return 1;

    }


    const version =
        Number(
            review.reviewVersion
        );


    return Number.isFinite(
        version
    )
        ? version
        : 1;

}

/* =========================================================
   GLOBAL ACCESS
========================================================= */

window.exportDashboardReport =
    exportDashboardReport;


function buildContractMonthlyReportData(

    year,

    month

){

    /* =====================================================
       REPORT PERIOD
    ===================================================== */

    const selectedYear =
        Number(
            year
        );


    const selectedMonth =
        Number(
            month
        );


    const monthNames = [

        "January",
        "February",
        "March",
        "April",
        "May",
        "June",
        "July",
        "August",
        "September",
        "October",
        "November",
        "December"

    ];


    const monthName =
        monthNames[
            selectedMonth - 1
        ] ||
        "Selected Month";


    const periodStart =
        new Date(

            selectedYear,

            selectedMonth - 1,

            1

        );


    const periodEnd =
        new Date(

            selectedYear,

            selectedMonth,

            0

        );


    periodStart.setHours(
        0,
        0,
        0,
        0
    );


    periodEnd.setHours(
        23,
        59,
        59,
        999
    );


    /* =====================================================
       CURRENT CONTRACTS ONLY
       -----------------------------------------------------
       IMPORTANT:
       Never build the report from deleted/archived
       historical objects.
    ===================================================== */

    const contracts =
        getCurrentContractsForMonthlyReport();


    /* =====================================================
       LOCAL DATE HELPERS
    ===================================================== */

    function parseDate(

        value

    ){

        if(
            !value
        ){

            return null;

        }


        const date =
            new Date(
                value
            );


        if(
            Number.isNaN(
                date.getTime()
            )
        ){

            return null;

        }


        return date;

    }


    function dateOnly(

        value

    ){

        const date =
            parseDate(
                value
            );


        if(
            !date
        ){

            return null;

        }


        return new Date(

            date.getFullYear(),

            date.getMonth(),

            date.getDate()

        );

    }


    function isDateInPeriod(

        value

    ){

        const date =
            parseDate(
                value
            );


        if(
            !date
        ){

            return false;

        }


        return (

            date >=
            periodStart &&

            date <=
            periodEnd

        );

    }


    function isSameMonth(

        value

    ){

        const date =
            parseDate(
                value
            );


        if(
            !date
        ){

            return false;

        }


        return (

            date.getFullYear() ===
            selectedYear &&

            date.getMonth() ===
            selectedMonth - 1

        );

    }


    /* =====================================================
       SECTION NAME
       -----------------------------------------------------
       Uses the helper already added above.

       NEVER expose section IDs in the report.
    ===================================================== */

    function getSectionName(

        contract

    ){

        return (

            typeof
            getContractReportSectionName ===
            "function"

                ?

                getContractReportSectionName(
                    contract
                )

                :

                "Home"

        );

    }


    /* =====================================================
       PAYMENT FREQUENCY
    ===================================================== */

    function getFrequencyText(

        value

    ){

        const frequency =
            Number(
                value
            );


        const labels = {

            1:
                "Monthly",

            2:
                "Every 2 months",

            3:
                "Every 3 months",

            4:
                "Every 4 months",

            6:
                "Every 6 months",

            12:
                "Yearly"

        };


        return (

            labels[
                frequency
            ] ||

            (
                frequency > 0

                    ?

                    `Every ${frequency} months`

                    :

                    "Not specified"

            )

        );

    }


    /* =====================================================
       CONTRACT STATUS
    ===================================================== */

    function getContractStatus(

        contract

    ){

        const today =
            new Date();


        today.setHours(
            0,
            0,
            0,
            0
        );


        const start =
            dateOnly(
                contract.startDate
            );


        const end =
            dateOnly(
                contract.endDate
            );


        if(
            contract.status ===
            "inactive"
        ){

            return "INACTIVE";

        }


        if(
            end &&
            end < today
        ){

            return "EXPIRED";

        }


        if(
            end &&

            end >=
            periodStart &&

            end <=
            periodEnd
        ){

            return "EXPIRING";

        }


        if(
            start &&
            start > today
        ){

            return "UPCOMING";

        }


        return "ACTIVE";

    }


    /* =====================================================
       REVIEWS
    ===================================================== */

    function getReviews(

        contract

    ){

        return Object.values(

            contract?.paymentReviews ||
            {}

        )
        .filter(

            review =>

                review &&
                typeof review ===
                "object"

        );

    }


    /* =====================================================
       REVIEW PAYMENT DATE
    ===================================================== */

    function getReviewPaymentDate(

        review

    ){

        return (

            review?.paymentDate ||

            review?.payment?.paymentDate ||

            null

        );

    }


    /* =====================================================
       REVIEW PAYMENT ID
    ===================================================== */

    function getReviewPaymentId(

        review

    ){

        const paymentDate =
            getReviewPaymentDate(
                review
            );


        return (

            review?.paymentId ||

            (
                paymentDate

                    ?

                    (

                        typeof
                        getContractPaymentReviewPaymentId ===
                        "function"

                            ?

                            getContractPaymentReviewPaymentId(
                                paymentDate
                            )

                            :

                            String(
                                paymentDate
                            )

                    )

                    :

                    null
            )

        );

    }


    /* =====================================================
       REVIEW VERSION
    ===================================================== */

    function getReviewVersion(

        review

    ){

        const version =
            Number(

                review?.reviewVersion ||

                review?.version ||

                1

            );


        return (

            Number.isFinite(
                version
            )

                ?

                version

                :

                1

        );

    }


    /* =====================================================
       REVIEW ACTIVITY DATE
       -----------------------------------------------------
       This is NOT the payment date.

       Priority:
       1. reviewDate
       2. reviewedAt
       3. savedAt
       4. createdAt
    ===================================================== */

    function getReviewActivityDate(

        review

    ){

        if(
            review?.reviewDate
        ){

            return review.reviewDate;

        }


        if(
            review?.reviewedAt
        ){

            return review.reviewedAt;

        }


        if(
            review?.savedAt
        ){

            return review.savedAt;

        }


        if(
            review?.createdAt
        ){

            return review.createdAt;

        }


        return null;

    }


    /* =====================================================
       REVIEW STATUS
    ===================================================== */

    function getReviewStatus(

        review

    ){

        if(
            !review
        ){

            return "PENDING";

        }


        if(
            review.paymentConfirmed ===
            true
        ){

            return "CONFIRMED";

        }


        if(
            review.paymentRejected ===
            true
        ){

            return "REJECTED";

        }


        if(
            review.paymentAnomaly ===
            true
        ){

            return "ANOMALY";

        }


        if(
            review.followUpRequired ===
            true
        ){

            return "FOLLOW-UP";

        }


        if(
            review.reviewed ===
            true
        ){

            return "REVIEWED";

        }


        return "PENDING";

    }


    /* =====================================================
       LATEST REVIEW FOR PAYMENT
    ===================================================== */

    function getLatestReviewForPayment(

        reviews,

        paymentDate

    ){

        const paymentId =

            typeof
            getContractPaymentReviewPaymentId ===
            "function"

                ?

                getContractPaymentReviewPaymentId(
                    paymentDate
                )

                :

                String(
                    paymentDate
                );


        const matching =
            reviews.filter(

                review =>

                    getReviewPaymentId(
                        review
                    ) ===
                    paymentId

            );


        if(
            matching.length ===
            0
        ){

            return null;

        }


        return matching.sort(

            (
                a,
                b
            ) =>

                getReviewVersion(
                    b
                ) -

                getReviewVersion(
                    a
                )

        )[0];

    }


    /* =====================================================
       CONTRACT PORTFOLIO
       -----------------------------------------------------
       One row = one CURRENT contract.

       Reviews NEVER duplicate portfolio contracts.
    ===================================================== */

    const portfolio =
        contracts.map(

            contract => {

                const contractValue =
                    Number(
                        contract.annualValue ||
                        0
                    );


                const reviews =
                    getReviews(
                        contract
                    );


                const status =
                    getContractStatus(
                        contract
                    );


                return {

                    id:
                        contract.id ||
                        "",

                    name:
                        contract.name ||
                        "Unnamed Contract",

                    company:
                        contract.company ||
                        "—",

                    type:
                        contract.type ||
                        "—",

                    reference:
                        contract.reference ||
                        "—",

                    section:
                        getSectionName(
                            contract
                        ),

                    contractValue:
                        contractValue,

                    /*
                        The contract value is the registered
                        value from Contract Info.

                        DO NOT divide it by 12.
                    */

                    annualValue:
                        contractValue,

                    paymentFrequency:
                        getFrequencyText(

                            contract.paymentFrequencyMonths

                        ),

                    paymentFrequencyMonths:
                        Number(
                            contract.paymentFrequencyMonths ||
                            0
                        ),

                    paymentMethod:
                        contract.paymentMethod ||
                        "—",

                    startDate:
                        contract.startDate ||
                        null,

                    endDate:
                        contract.endDate ||
                        null,

                    nextPaymentDate:
                        contract.nextPaymentDate ||
                        null,

                    responsible:
                        contract.responsible ||
                        "—",

                    description:
                        contract.description ||
                        "",

                    status:
                        status,

                    reviewCount:
                        reviews.length,

                    reviewVersions:
                        reviews.length

                };

            }

        );


    /* =====================================================
       PAYMENT ACTIVITY
       -----------------------------------------------------
       ONE COMPLETED PAYMENT = ONE PAYMENT.

       Multiple review versions of the same payment
       NEVER create multiple payments.

       PAYMENT AMOUNT = CONTRACT VALUE.
       No /12.
    ===================================================== */

    const payments =
        [];


    contracts.forEach(

        contract => {

            const contractValue =
                Number(
                    contract.annualValue ||
                    0
                );


            const reviews =
                getReviews(
                    contract
                );


            const completedByPayment =
                new Map();


            reviews.forEach(

                review => {

                    if(
                        review.paymentClosed !==
                        true
                    ){

                        return;

                    }


                    const paymentDate =
                        getReviewPaymentDate(
                            review
                        );


                    if(
                        !paymentDate
                    ){

                        return;

                    }


                    const paymentKey =
                        getReviewPaymentId(
                            review
                        ) ||
                        String(
                            paymentDate
                        );


                    const existing =
                        completedByPayment.get(
                            paymentKey
                        );


                    if(

                        !existing ||

                        getReviewVersion(
                            review
                        ) >

                        existing.reviewVersion

                    ){

                        completedByPayment.set(

                            paymentKey,

                            {

                                paymentDate:
                                    paymentDate,

                                review:
                                    review,

                                reviewVersion:
                                    getReviewVersion(
                                        review
                                    )

                            }

                        );

                    }

                }

            );


            completedByPayment.forEach(

                payment => {

                    if(
                        !isDateInPeriod(
                            payment.paymentDate
                        )
                    ){

                        return;

                    }


                    const latestReview =
                        getLatestReviewForPayment(

                            reviews,

                            payment.paymentDate

                        ) ||

                        payment.review;


                    const paymentReviews =
                        reviews.filter(

                            review =>

                                getReviewPaymentId(
                                    review
                                ) ===

                                getReviewPaymentId(
                                    payment.review
                                )

                        );


                    /*
                        IMPORTANT:
                        The amount is exactly the value
                        registered on the contract.
                    */

                    const amount =
                        contractValue;


                    payments.push({

                        contractId:
                            contract.id ||
                            "",

                        name:
                            contract.name ||
                            "Unnamed Contract",

                        company:
                            contract.company ||
                            "—",

                        section:
                            getSectionName(
                                contract
                            ),

                        paymentDate:
                            payment.paymentDate,

                        amount:
                            amount,

                        reviewCount:
                            paymentReviews.length,

                        reviewVersions:
                            paymentReviews.length,

                        status:
                            getReviewStatus(
                                latestReview
                            ),

                        paymentClosedAt:
                            payment.review.paymentClosedAt ||
                            null,

                        paymentClosedBy:
                            payment.review.paymentClosedBy ||
                            null,

                        review:
                            latestReview

                    });

                }

            );

        }

    );


    payments.sort(

        (
            a,
            b
        ) => {

            const dateA =
                parseDate(
                    a.paymentDate
                );


            const dateB =
                parseDate(
                    b.paymentDate
                );


            if(
                !dateA &&
                !dateB
            ){

                return 0;

            }


            if(
                !dateA
            ){

                return 1;

            }


            if(
                !dateB
            ){

                return -1;

            }


            return (
                dateA -
                dateB
            );

        }

    );


    /* =====================================================
       REVIEW ACTIVITY
       -----------------------------------------------------
       IMPORTANT:

       ONLY reviews whose OWN activity date is inside
       the selected reporting month are included.

       A payment from another month does NOT make its
       review appear in this section.
    ===================================================== */

    const periodReviews =
        [];


    contracts.forEach(

        contract => {

            const reviews =
                getReviews(
                    contract
                );


            reviews.forEach(

                review => {

                    const activityDate =
                        getReviewActivityDate(
                            review
                        );


                    if(
                        !isDateInPeriod(
                            activityDate
                        )
                    ){

                        return;

                    }


                    periodReviews.push({

                        contractId:
                            contract.id ||
                            "",

                        contractName:
                            contract.name ||
                            "Unnamed Contract",

                        company:
                            contract.company ||
                            "—",

                        section:
                            getSectionName(
                                contract
                            ),

                        paymentDate:
                            getReviewPaymentDate(
                                review
                            ),

                        reviewDate:
                            activityDate,

                        reviewVersion:
                            getReviewVersion(
                                review
                            ),

                        reviewType:
                            review.reviewType ||
                            "—",

                        reviewTitle:
                            review.reviewTitle ||
                            "Payment Review",

                        status:
                            getReviewStatus(
                                review
                            ),

                        createdAt:
                            review.createdAt ||
                            null,

                        createdBy:
                            review.createdBy ||
                            "—",

                        reviewedAt:
                            review.reviewedAt ||
                            null,

                        reviewedBy:
                            review.reviewedBy ||
                            "—",

                        savedAt:
                            review.savedAt ||
                            null,

                        savedBy:
                            review.savedBy ||
                            "—",

                        followUpRequired:
                            review.followUpRequired ===
                            true,

                        issueResolved:
                            review.issueResolved ===
                            true,

                        notes:
                            review.notes ||
                            ""

                    });

                }

            );

        }

    );


    periodReviews.sort(

        (
            a,
            b
        ) => {

            const dateA =
                parseDate(
                    a.reviewDate
                );


            const dateB =
                parseDate(
                    b.reviewDate
                );


            if(
                dateA &&
                dateB
            ){

                const difference =
                    dateA -
                    dateB;


                if(
                    difference !==
                    0
                ){

                    return difference;

                }

            }


            return (

                Number(
                    a.reviewVersion ||
                    0
                ) -

                Number(
                    b.reviewVersion ||
                    0
                )

            );

        }

    );


    /* =====================================================
       REVIEW HISTORY
       -----------------------------------------------------
       Only payment review histories that actually have
       review activity during the selected month are shown.

       A historical review from another month is NOT pulled
       into the report simply because its payment exists.
    ===================================================== */

    const reviewPaymentGroups =
        {};


    contracts.forEach(

        contract => {

            const reviews =
                getReviews(
                    contract
                );


            const grouped =
                {};


            reviews.forEach(

                review => {

                    const paymentDate =
                        getReviewPaymentDate(
                            review
                        );


                    if(
                        !paymentDate
                    ){

                        return;

                    }


                    const paymentId =
                        getReviewPaymentId(
                            review
                        ) ||
                        String(
                            paymentDate
                        );


                    if(
                        !grouped[
                            paymentId
                        ]
                    ){

                        grouped[
                            paymentId
                        ] = [];

                    }


                    grouped[
                        paymentId
                    ].push(
                        review
                    );

                }

            );


            Object.entries(
                grouped
            ).forEach(

                (
                    [
                        paymentId,
                        reviewsForPayment
                    ]
                ) => {

                    /*
                        IMPORTANT:
                        A history is relevant ONLY if at least
                        one of its review versions was opened/
                        saved/reviewed during this month.
                    */

                    const monthlyReviews =
                        reviewsForPayment.filter(

                            review =>

                                isDateInPeriod(

                                    getReviewActivityDate(
                                        review
                                    )

                                )

                        );


                    if(
                        monthlyReviews.length ===
                        0
                    ){

                        return;

                    }


                    reviewsForPayment.sort(

                        (
                            a,
                            b
                        ) =>

                            getReviewVersion(
                                a
                            ) -

                            getReviewVersion(
                                b
                            )

                    );


                    const paymentDate =
                        getReviewPaymentDate(

                            reviewsForPayment[0]

                        );


                    const latest =
                        reviewsForPayment[
                            reviewsForPayment.length - 1
                        ];


                    reviewPaymentGroups[

                        `${contract.id}_${paymentId}`

                    ] = {

                        contractId:
                            contract.id,

                        contractName:
                            contract.name ||
                            "Unnamed Contract",

                        company:
                            contract.company ||
                            "—",

                        section:
                            getSectionName(
                                contract
                            ),

                        paymentDate:
                            paymentDate,

                        paymentAmount:
                            Number(
                                contract.annualValue ||
                                0
                            ),

                        versions:
                            reviewsForPayment,

                        monthlyVersions:
                            monthlyReviews,

                        versionCount:
                            reviewsForPayment.length,

                        monthlyVersionCount:
                            monthlyReviews.length,

                        latest:
                            latest,

                        finalStatus:
                            getReviewStatus(
                                latest
                            )

                    };

                }

            );

        }

    );


    const reviewHistories =
        Object.values(
            reviewPaymentGroups
        )
        .sort(

            (
                a,
                b
            ) => {

                const dateA =
                    parseDate(
                        a.paymentDate
                    );


                const dateB =
                    parseDate(
                        b.paymentDate
                    );


                if(
                    dateA &&
                    dateB
                ){

                    return (
                        dateA -
                        dateB
                    );

                }


                return 0;

            }

        );


    /* =====================================================
       EXPIRING CONTRACTS
    ===================================================== */

    const expiring =
        portfolio.filter(

            contract =>

                isSameMonth(
                    contract.endDate
                )

        );


    /* =====================================================
       UPCOMING PAYMENTS
       -----------------------------------------------------
       Current nextPaymentDate.

       Only current contracts are considered.
    ===================================================== */

    const upcomingPayments =
        portfolio

            .filter(

                contract => {

                    const date =
                        parseDate(
                            contract.nextPaymentDate
                        );


                    if(
                        !date
                    ){

                        return false;

                    }


                    const horizon =
                        new Date(
                            periodEnd
                        );


                    horizon.setDate(

                        horizon.getDate() +
                        90

                    );


                    return (

                        date >=
                        periodStart &&

                        date <=
                        horizon

                    );

                }

            )

            .sort(

                (
                    a,
                    b
                ) => {

                    const dateA =
                        parseDate(
                            a.nextPaymentDate
                        );


                    const dateB =
                        parseDate(
                            b.nextPaymentDate
                        );


                    if(
                        !dateA &&
                        !dateB
                    ){

                        return 0;

                    }


                    if(
                        !dateA
                    ){

                        return 1;

                    }


                    if(
                        !dateB
                    ){

                        return -1;

                    }


                    return (
                        dateA -
                        dateB
                    );

                }

            );


    /* =====================================================
       SECTION DISTRIBUTION
    ===================================================== */

    const sectionCounter =
        {};


    portfolio.forEach(

        contract => {

            const section =
                contract.section ||
                "Home";


            sectionCounter[
                section
            ] =

                (
                    sectionCounter[
                        section
                    ] ||
                    0
                ) +

                1;

        }

    );


    const sectionDistribution =
        Object.entries(
            sectionCounter
        )
        .sort(

            (
                a,
                b
            ) =>

                b[1] -
                a[1]

        );


    /* =====================================================
       PAYMENT FREQUENCY DISTRIBUTION
    ===================================================== */

    const frequencyCounter =
        {};


    portfolio.forEach(

        contract => {

            const frequency =
                contract.paymentFrequency ||
                "Not specified";


            frequencyCounter[
                frequency
            ] =

                (
                    frequencyCounter[
                        frequency
                    ] ||
                    0
                ) +

                1;

        }

    );


    const frequencyDistribution =
        Object.entries(
            frequencyCounter
        )
        .sort(

            (
                a,
                b
            ) =>

                b[1] -
                a[1]

        );


    /* =====================================================
       METRICS
    ===================================================== */

    const totalContracts =
        portfolio.length;


    const activeContracts =
        portfolio.filter(

            contract =>

                contract.status ===
                "ACTIVE"

        ).length;


    const expiredContracts =
        portfolio.filter(

            contract =>

                contract.status ===
                "EXPIRED"

        ).length;


    const totalContractValue =
        portfolio.reduce(

            (
                total,
                contract
            ) =>

                total +

                Number(
                    contract.contractValue ||
                    0
                ),

            0

        );


    /*
        Total paid in the month.

        Every completed payment contributes the
        registered contract value.
    */

    const totalPaid =
        payments.reduce(

            (
                total,
                payment
            ) =>

                total +

                Number(
                    payment.amount ||
                    0
                ),

            0

        );


    const completedPayments =
        payments.length;


    /*
        Because each payment uses the fixed contract value,
        averagePayment reflects the average VALUE OF A
        COMPLETED PAYMENT.

        It is NOT annualValue / 12.
    */

    const averagePayment =
        completedPayments > 0

            ?

            totalPaid /
            completedPayments

            :

            0;


    const highestPayment =
        payments.reduce(

            (
                highest,
                payment
            ) =>

                Math.max(

                    highest,

                    Number(
                        payment.amount ||
                        0
                    )

                ),

            0

        );


    const contractsExpiring =
        expiring.length;


    const expiringContractValue =
        expiring.reduce(

            (
                total,
                contract
            ) =>

                total +

                Number(
                    contract.contractValue ||
                    0
                ),

            0

        );


    /*
        REVIEW METRICS
        ----------------

        These now refer ONLY to reviews whose activity
        date belongs to the selected reporting month.
    */

    const reviewsCreated =
        periodReviews.length;


    const reviewsConfirmed =
        periodReviews.filter(

            review =>

                review.status ===
                "CONFIRMED"

        ).length;


    const reviewsRejected =
        periodReviews.filter(

            review =>

                review.status ===
                "REJECTED"

        ).length;


    const reviewAnomalies =
        periodReviews.filter(

            review =>

                review.status ===
                "ANOMALY"

        ).length;


    const followUps =
        periodReviews.filter(

            review =>

                review.followUpRequired

        ).length;


    const resolvedIssues =
        periodReviews.filter(

            review =>

                review.issueResolved

        ).length;


    /*
        Number of payments which had more than one
        review version DURING the selected month.

        This is intentionally based on monthly versions,
        not the complete lifetime history of the contract.
    */

    const multipleVersionPayments =
        reviewHistories.filter(

            payment =>

                Number(
                    payment.monthlyVersionCount ||
                    0
                ) > 1

        );


    const multipleReviewPayments =
        multipleVersionPayments.length;


    const scheduledPayments =
        portfolio.filter(

            contract =>

                isSameMonth(
                    contract.nextPaymentDate
                )

        ).length;


    const completionRate =

        scheduledPayments > 0

            ?

            (
                completedPayments /
                scheduledPayments
            ) *
            100

            :

            null;


    /* =====================================================
       MANAGEMENT FLAGS
    ===================================================== */

    const managementFlags =
        [];


    if(
        contractsExpiring >
        0
    ){

        managementFlags.push({

            type:
                "EXPIRY",

            severity:
                "attention",

            title:
                "Contract expiries",

            text:

                `${contractsExpiring} contract(s) expire during ${monthName} ${selectedYear}.`

        });

    }


    if(
        reviewAnomalies >
        0
    ){

        managementFlags.push({

            type:
                "ANOMALY",

            severity:
                "critical",

            title:
                "Payment anomalies",

            text:

                `${reviewAnomalies} payment review(s) contain an anomaly.`

        });

    }


    if(
        followUps >
        0
    ){

        managementFlags.push({

            type:
                "FOLLOW_UP",

            severity:
                "attention",

            title:
                "Follow-up required",

            text:

                `${followUps} review(s) require follow-up.`

        });

    }


    if(
        managementFlags.length ===
        0
    ){

        managementFlags.push({

            type:
                "NORMAL",

            severity:
                "normal",

            title:
                "Month status",

            text:

                `No payment anomalies, outstanding follow-ups or contract expiries were identified for ${monthName} ${selectedYear}.`

        });

    }


    /* =====================================================
       FINAL REPORT OBJECT
    ===================================================== */

    return {

        year:
            selectedYear,

        month:
            selectedMonth,

        monthName:
            monthName,

        generatedAt:
            Date.now(),

        periodStart:
            periodStart.toISOString(),

        periodEnd:
            periodEnd.toISOString(),


        /* =================================================
           MAIN DATA
        ================================================= */

        portfolio:
            portfolio,

        payments:
            payments,

        /*
            ONLY monthly review activity.
        */

        reviews:
            periodReviews,

        /*
            ONLY review histories with at least one
            review activity in the selected month.
        */

        reviewHistories:
            reviewHistories,

        multipleVersionPayments:
            multipleVersionPayments,

        expiring:
            expiring,

        upcomingPayments:
            upcomingPayments,


        /* =================================================
           DISTRIBUTIONS
        ================================================= */

        sectionDistribution:
            sectionDistribution,

        frequencyDistribution:
            frequencyDistribution,


        /* =================================================
           MANAGEMENT
        ================================================= */

        managementFlags:
            managementFlags,


        /* =================================================
           METRICS
        ================================================= */

        metrics: {

            totalContracts:
                totalContracts,

            activeContracts:
                activeContracts,

            expiredContracts:
                expiredContracts,

            totalContractValue:
                totalContractValue,

            totalAnnualValue:
                totalContractValue,

            scheduledPayments:
                scheduledPayments,

            completedPayments:
                completedPayments,

            completionRate:
                completionRate,

            totalPaid:
                totalPaid,

            averagePayment:
                averagePayment,

            highestPayment:
                highestPayment,

            largestPayment:
                highestPayment,

            contractsExpiring:
                contractsExpiring,

            expiringAnnualValue:
                expiringContractValue,

            expiringContractValue:
                expiringContractValue,

            /*
                Reviews = reviews actually active in
                the selected month.
            */

            reviewsCreated:
                reviewsCreated,

            reviewsConfirmed:
                reviewsConfirmed,

            reviewsRejected:
                reviewsRejected,

            reviewAnomalies:
                reviewAnomalies,

            followUps:
                followUps,

            resolvedIssues:
                resolvedIssues,

            multipleReviewPayments:
                multipleReviewPayments,

            reviewVersions:
                periodReviews.length,

            multipleVersionContracts:
                multipleVersionPayments.length

        }

    };

}   

/* =========================================================
   GLOBAL ACCESS
========================================================= */

window.buildContractMonthlyReportData =
    buildContractMonthlyReportData;

/* =========================================================
   CONTRACT REPORT
   LOAD PDF ENGINE
========================================================= */

async function loadContractReportPdfEngine(){

    /* =====================================================
       ALREADY LOADED
    ===================================================== */

    if(
        window.jspdf &&
        typeof window.jspdf.jsPDF ===
        "function"
    ){

        return window.jspdf.jsPDF;

    }


    /* =====================================================
       SOURCES
    ===================================================== */

    const sources = [

        "https://cdn.jsdelivr.net/npm/jspdf@2.5.2/dist/jspdf.umd.min.js",

        "https://unpkg.com/jspdf@2.5.2/dist/jspdf.umd.min.js",

        "https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.2/jspdf.umd.min.js"

    ];


    /* =====================================================
       TRY SOURCES
    ===================================================== */

    for(
        const source of sources
    ){

        try{

            await new Promise(

                (
                    resolve,
                    reject
                ) => {

                    const oldScript =
                        document.getElementById(
                            "contractReportJsPdfScript"
                        );


                    if(
                        oldScript
                    ){

                        oldScript.remove();

                    }


                    const script =
                        document.createElement(
                            "script"
                        );


                    script.id =
                        "contractReportJsPdfScript";


                    script.src =
                        source;


                    script.async =
                        true;


                    script.onload =
                        () => {

                            let attempts =
                                0;


                            const checkEngine =
                                () => {

                                    attempts++;


                                    if(

                                        window.jspdf &&

                                        typeof
                                        window.jspdf.jsPDF ===
                                        "function"

                                    ){

                                        resolve();

                                        return;

                                    }


                                    if(
                                        attempts >=
                                        20
                                    ){

                                        reject(

                                            new Error(
                                                "PDF_ENGINE_NOT_EXPOSED"
                                            )

                                        );

                                        return;

                                    }


                                    setTimeout(
                                        checkEngine,
                                        100
                                    );

                                };


                            checkEngine();

                        };


                    script.onerror =
                        () => {

                            reject(

                                new Error(
                                    "PDF_ENGINE_LOAD_FAILED"
                                )

                            );

                        };


                    document.head.appendChild(
                        script
                    );

                }

            );


            if(

                window.jspdf &&

                typeof
                window.jspdf.jsPDF ===
                "function"

            ){

                console.info(
                    "PDF ENGINE LOADED:",
                    source
                );


                return window.jspdf.jsPDF;

            }

        }
        catch(error){

            console.warn(

                "PDF ENGINE SOURCE FAILED:",

                source,

                error

            );

        }

    }


    throw new Error(
        "PDF_ENGINE_LOAD_FAILED"
    );

}


/* =========================================================
   GLOBAL ACCESS
========================================================= */

window.loadContractReportPdfEngine =
    loadContractReportPdfEngine;

